algorithms.pseudocode:
Input: Weight matrix W, max cycle length L
Output: Minimum cycle cost g

g <- infinity
for l = 1 to L:
  for each (r1,...,rl) in (Fin a)^l:
    for each (c1,...,cl) in (Fin b)^l:
      g <- min(g, sum_i W(ri, ci))
return g

algorithms.code:
def compute_cycle_systole(W):
    """Compute minimum alternating cycle cost."""
    return int(W.min())  # Length-1 cycles: min entry

def decompose_protocol(R, n, messages, costs):
    """Decompose protocol into consecutive blocks."""
    return [(k*n, messages[k*n:(k+1)*n], costs[k*n:(k+1)*n])
            for k in range(R // n)]

def rectangle_bound(W, R, n):
    """Evaluate cycle-systolic rectangle bound."""
    g = int(W.min())
    return g * (R // n)
